-- The original five-table model: repositories, learning objects, package versions, attempts and the
-- evidence outbox. Extended by 007_production_runtime.sql.
create table repository (repository_id uuid primary key, slug text not null unique, display_name text not null, status text not null check (status in ('DRAFT','ACTIVE','SUSPENDED','RETIRING','RETIRED')), created_at timestamptz not null default now(), revision int not null default 1);
create table learning_object (object_id uuid primary key, repository_id uuid not null references repository(repository_id), active_object_version_id uuid, status text not null check (status in ('DRAFT','VALIDATING','PUBLISHED','SUPERSEDED','SUSPENDED','RETIRED')), created_at timestamptz not null default now());
create table package_version (package_version_id uuid primary key, package_id uuid not null, object_id uuid not null references learning_object(object_id), semver text not null, sha256 text not null, delivery_profile text not null check (delivery_profile in ('native-web-package')), entry_point text not null, status text not null check (status in ('UPLOADED','VALIDATING','VALIDATED','PUBLISHED','SUPERSEDED','QUARANTINED','RETIRED')), published_at timestamptz, created_at timestamptz not null default now(), unique (package_id, semver));
create table attempt (attempt_id uuid primary key, repository_id uuid not null references repository(repository_id), object_version_id uuid not null, package_version_id uuid not null references package_version(package_version_id), pseudonymous_subject_id text not null, consumer_id text not null, status text not null check (status in ('CREATED','STARTED','COMPLETED')), revision int not null default 1, state_payload jsonb, created_at timestamptz not null default now(), started_at timestamptz, completed_at timestamptz, correlation_id text not null);
create table evidence_outbox (outbox_id uuid primary key, statement_id uuid not null unique, repository_id uuid not null, attempt_id uuid not null references attempt(attempt_id), package_version_id uuid not null, payload jsonb not null, status text not null check (status in ('PENDING','FORWARDED','FAILED')), attempts int not null default 0, last_error text, created_at timestamptz not null default now(), forwarded_at timestamptz, correlation_id text not null);
create index evidence_outbox_pending_idx on evidence_outbox(status) where status = 'PENDING';
